function createSpaceInvaders(gameCanvasId, width, height) {
  const canvas = document.getElementById(gameCanvasId);
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext('2d');

  let gameObjects = [];

  class GameObject {
    constructor(x, y, w, h, color) {
      this.x = x;
      this.y = y;
      this.w = w;
      this.h = h;
      this.color = color;
    }

    draw(ctx) {
      ctx.fillStyle = this.color;
      ctx.fillRect(this.x, this.y, this.w, this.h);
    }
  }

  class Player extends GameObject {
    constructor(x, y, w, h, color) {
      super(x, y, w, h, color);
      this.speed = 5;
    }

    update(deltaTime) {
      if (keys[37]) this.x -= this.speed;
      if (keys[39]) this.x += this.speed;
    }
  }

  class Bullet extends GameObject {
    constructor(x, y, w, h, color, speed) {
      super(x, y, w, h, color);
      this.speed = speed;
    }

    update(deltaTime) {
      this.y -= this.speed;
    }
  }

  class Invader extends GameObject {
    constructor(x, y, w, h, color) {
      super(x, y, w, h, color);
      this.speed = 0.1;
    }

    update(deltaTime) {
      if (Math.random() < 0.01) {
        let bullet = new Bullet(
          this.x + this.w / 2,
          this.y + this.h,
          2,
          10,
          'white',
          2
        );
        gameObjects.push(bullet);
      }
    }
  }

  const player = new Player(canvas.width / 2, canvas.height - 50, 20, 50, 'blue');
  gameObjects.push(player);

  let invaderRows = 3;
  let invaderCols = 4;
  let invaderYGap = 20;
  let invaderXGap = 40;
  let invaderSize = 30;

  for (let row = 0; row < invaderRows; row++) {
    for (let col = 0; col < invaderCols; col++) {
      let invader = new Invader(
        invaderXGap + (invaderSize + invaderXGap) * col,
        invaderYGap + (invaderSize + invaderYGap) * row,
        invaderSize,
        invaderSize,
        'white'
      );
      gameObjects.push(invader);
    }
  }

  let lastFireTime = 0;

  function updateGame(deltaTime) {
    for (let i = gameObjects.length - 1; i >= 0; i--) {
      let obj = gameObjects[i];
      if (obj.constructor.name === 'Invader' && obj.y > canvas.height) {
        gameOver();
        return;
      }
      obj.update(deltaTime);

      if (obj.constructor.name === 'Bullet') {
        if (obj.y < 0) {
          gameObjects.splice(i, 1);
        }
      }
    }

    for (let i = gameObjects.length - 1; i >= 0; i--) {
      for (let j = i - 1; j >= 0; j--) {
        let obj1 = gameObjects[i];
        let obj2 = gameObjects[j];
        if (collision(obj1, obj2)) {
          handleCollision(obj1, obj2);
        }
      }
    }

    let now = performance.now();
    if (now - lastFireTime > 1000) {
      if (keys[32]) {
        let bullet = new Bullet(
          player.x + player.w / 2,
          player.y - 5,
          3,
          5,
          'blue',
          3
        );
        gameObjects.push(bullet);
        lastFireTime = now;
      }
    }
  }

  function drawGame() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    for (let i = 0; i < gameObjects.length; i++) {
      gameObjects[i].draw(ctx);
    }
  }

  function collision(obj1, obj2) {
    return (
      obj1.x < obj2.x + obj2.w &&
      obj1.x + obj1.w > obj2.x &&
      obj1.y < obj2.y + obj2.h &&
      obj1.y + obj1.h > obj2.y
    );
  }

  function handleCollision(obj1, obj2) {
    if (obj1.constructor.name === 'Bullet' && obj2.constructor.name === 'Invader') {
      gameObjects.splice(gameObjects.indexOf(obj1), 1);
      gameObjects.splice(gameObjects.indexOf(obj2), 1);
    }
  }

  let keys = [];
  window.addEventListener('keydown', (event) => {
    keys[event.keyCode] = true;
  });
  window.addEventListener('keyup', (event) => {
    keys[event.keyCode] = false;
  });

  function gameLoop() {
    let now = performance.now();
    let deltaTime = (now - lastUpdate) / 1000;
    updateGame(deltaTime);
    lastUpdate = now;
    drawGame();
    requestAnimationFrame(gameLoop);
  }

  function gameOver() {
    alert('Game Over!');
    location.reload();
  }

  let lastUpdate = performance.now();
  gameLoop();
}
